const rows=(a:m.Matrix)=>table(['Row',...m.range(a[0].length).map(i=>`Column ${i+1}`)],a.map((r,i)=>[i+1,...r]));
function records(data:string){const v=data.trim().split(/[;\n]+/).map(m.numbers);m.requireValue(v.length>=4&&v.length<=200&&v[0].length>=2&&v[0].length<=6&&v.every(row=>row.length===v[0].length),'Use 4–200 complete rows, each with 1–5 predictors followed by the response.');return v;}
function points(data:string){const v=records(data);m.requireValue(v[0].length===2,'Enter x,y rows for this single-predictor experiment.');return v;}
